        private async Task<bool> InitLhmWithRetryAsync(int maxAttempts = 3, int delayMs = 1200)
        {
            for (int attempt = 1; attempt <= maxAttempts; attempt++)
            {
                if (attempt > 1) await Task.Delay(delayMs);
                SMDWin.Services.TempReader? reader = null;
                await Task.Run(() =>
                {
                    try { reader = new SMDWin.Services.TempReader(); }
                    catch (Exception ex) { AppLogger.Warning(ex, "InitLhmWithRetryAsync"); }
                });
                if (reader != null)
                {
                    _tempReader = reader;
                    if (reader.Backend.StartsWith("LibreHardwareMonitor")) return true;
                }
                if (attempt < maxAttempts)
                    AppLogger.Info($"InitLhmWithRetryAsync: attempt {attempt} did not enable LHM (backend={reader?.Backend ??"null"}), retrying...");
            }
            return _tempReader?.Backend.StartsWith("LibreHardwareMonitor") == true;
        }

        /// <summary>Waits for the main window to show (and the splash to close), then offers to install PawnIO.</summary>
        private async Task OfferPawnIOAfterStartupAsync()
        {
            try
            {
                for (int i = 0; i < 120 && !this.IsVisible; i++) await Task.Delay(250);
                // also after the splash has closed: a window over the splash is hidden behind it
                for (int i = 0; i < 160 && System.Windows.Application.Current.Windows.OfType<SplashWindow>().Any(w => w.IsVisible); i++) await Task.Delay(250);
                await Task.Delay(1500);
                if (_betaNoticeTask != null) await _betaNoticeTask;   // one start-up dialog at a time: the beta notice first
                await OfferPawnIOInstallAsync();
                RefreshPawnIoStatus();
                SMDWin.Services.BootTiming.Mark("PawnIO install offer (after start) finished");
            }
            catch (Exception ex) { AppLogger.Warning(ex, "OfferPawnIOAfterStartupAsync"); }
        }

        private async Task InitTempReaderThenStartTimer()
        {

            StartTempTimer();
            // no fixed pause: only yield the thread, so the Dashboard load starts in parallel with the sensors
            await Task.Yield();

            bool pawnioOk = SMDWin.Services.PawnIOService.IsInstalled();
            if (!pawnioOk)
            {
                AppLogger.Warning("BOOT-DIAG: PawnIOService.IsInstalled() returned FALSE at +{0}ms from boot — showing the install dialog. If PawnIO is in fact already installed, this explains a slow boot (unwanted dialog).", _appStartStopwatch.ElapsedMilliseconds);

                // The install dialog is NOT shown during the splash: it would block start-up (a modal window over the splash, 12 s
                // failsafe). Start the sensors now; the offer appears after the window is visible.
                _ = OfferPawnIOAfterStartupAsync();
            }
            else
            {
                // the driver is installed: once the sensors had time to answer, the status (Settings, sidebar) says whether
                // they really do, instead of "active" on its own
                _ = Dispatcher.InvokeAsync(async () =>
                {
                    await Task.Delay(TimeSpan.FromSeconds(40));
                    if (CpuSensorsAnswer() == false)
                        AppLogger.Warning("PawnIO is installed, but no processor temperature comes from the sensors after 40 s (sensor: {0})", _lastTempSnap?.CpuSensorName ?? "none");
                    RefreshPawnIoStatus();
                });
            }

            SMDWin.Services.StartupProgress.Report(SMDWin.Services.StartupStep.Lhm, LanguageService.S("Splash", "MsgLhm"));
            await InitLhmWithRetryAsync();
            SMDWin.Services.BootTiming.Mark($"Sensors ready (LHM, IGCL, WMI), backend={_tempReader?.Backend ??"null"}");

            try
            {
                if (_tempReader != null)
                {
                    // The "Auto" CPU threshold is computed on every start: from the CPU's TjMax (the database/heuristic in TempReader) with
                    // a safety margin, or 90°C by default if TjMax could not be estimated at all.
                    uint tjMax = _tempReader.EstimatedTjMaxC;
                    const float marginC = 10f;
                    const float defaultThreshold = 90f;
                    float dynamicThreshold = tjMax > 0 ? Math.Max(80f, tjMax - marginC) : defaultThreshold;
                    // "Auto" in Settings › Alerts; a value chosen there takes priority (ApplyTempLimits)
                    _autoCpuTempLimit = dynamicThreshold;
                    ApplyTempLimits();
                    UpdateTempLimitDescriptions();
                    SettingsService.Save();
                    AppLogger.Info("S-DYNAMIC-TJMAX: estimated TjMax={0}°C → default CPU threshold={1}°C (recomputed automatically on every start)", tjMax, dynamicThreshold);
                }
            }
            catch (Exception ex) { AppLogger.Debug(ex.Message); }

            if (TxtTempBackend != null)
            {
                if (_tempReader != null)
                {
                    bool hasAnyData = _tempReader.Backend.StartsWith("LibreHardwareMonitor") || _tempReader.Backend.StartsWith("WMI");
                    TxtTempBackend.Text = hasAnyData ? $"Sensor: {_tempReader.Backend}" : $"{_tempReader.Backend}";
                }
                else
                    TxtTempBackend.Text = _LS("Common", "SensorUnavailableAdmin");
            }
            SMDWin.Services.StartupProgress.Report(SMDWin.Services.StartupStep.Sensors,
                _tempReader != null
                    ? string.Format(LanguageService.S("Splash", "MsgSensorsDetected"), _tempReader.Backend)
                    : LanguageService.S("Splash", "MsgSensorsReading"));
            StartTempTimer();
            _ = CheckCrashBadgeOnStartupAsync();
            _ = CheckEventsBadgeOnStartupAsync();
        }

        /// <summary>Visibly signals (and in the log, only on the transition) when the sensor data is too old to be shown as live.</summary>
        private void UpdateSensorStaleState()
        {
            var raw = _lastTempSnapRaw;
            bool stale = raw != null && !raw.IsFresh(_sensorLiveMaxAge);
            if (stale == _sensorDataStale) return;
            _sensorDataStale = stale;
            if (stale)
                AppLogger.Warning("SENSOR-STALE: the last real reading is {0:F0}s old (limit {1:F0}s) — values are shown as unavailable until a new reading.",
                    raw!.Age.TotalSeconds, _sensorLiveMaxAge.TotalSeconds);
            else
                AppLogger.Info("SENSOR-STALE: readings are back to normal.");
            try
            {
                if (TxtTempBackend != null && _tempReader != null)
                    TxtTempBackend.Text = stale
                        ? $"Sensor: {_tempReader.Backend} — {_LS("Common", "SensorDataStale")}"
                        : $"Sensor: {_tempReader.Backend}";
            }
            catch (Exception ex) { AppLogger.Debug(ex.Message); }
        }

        private void InitTempReader()
        {
            _ = Task.Run(async () =>
            {
                try { _tempReader = new SMDWin.Services.TempReader(); }
                catch (Exception ex) { AppLogger.Warning(ex, "MainWindow.InitTempReader"); }
                // Marshal back to UI thread (non-blocking)
                await Dispatcher.InvokeAsync(() =>
                {
                    if (TxtTempBackend != null)
                        if (TxtTempBackend != null) TxtTempBackend.Text = _tempReader != null
                            ? $"Sensor: {_tempReader.Backend}"
                            : _LS("Common", "SensorUnavailableAdmin");
                });
            });
        }

        private bool _tempTimerStarted = false;
        private void StartTempTimer()
        {
            if (_tempTimerStarted) return;   // anti dublu-subscribe
            _tempTimerStarted = true;
            _tempTimer.Interval = TimeSpan.FromSeconds(SettingsService.Current.RefreshInterval);
            _tempTimer.Tick += OnTempTick;
            _tempTimer.Start();

            // Background continuous monitoring — 30s interval, runs always (even minimized)
            StartBackgroundMonitoring();

            InitDataProvider();

            // PerformanceCounters polled on background thread — never blocks UI
            StartPerfCounterThread();

            // Smooth chart render at 30fps — animates the chart scrolling continuously
            // between real data samples so it looks fluid instead of jumping every second
            if (!_smoothRenderTimer.IsEnabled)
            {
                _smoothRenderTimer.Interval = TimeSpan.FromMilliseconds(100); // ~30fps
                _smoothRenderTimer.Tick += OnSmoothRenderTick;
                _smoothRenderTimer.Start();
            }
        }

        // ── Smooth chart: 1-second lag buffer with 30fps interpolation ─────────
        // Simple subframe counter for chart scroll animation
        private double _chartSubFrame = 0.0;
        private double _chartSubFrameStep = 0.0;

        private void OnSmoothRenderTick(object? s, EventArgs e)
        {
            // Skip entirely when minimized — no point rendering a hidden chart at 30fps
            if (WindowState == System.Windows.WindowState.Minimized) return;
            if (PanelStress?.Visibility != Visibility.Visible) return;
            if (!_tempDataFresh) return;
            _tempDataFresh = false;
            double refreshMs = SettingsService.Current.RefreshInterval * 1000.0;
            _chartSubFrameStep = 33.0 / refreshMs;
            _chartSubFrame = (_chartSubFrame + _chartSubFrameStep) % 2.0; // wrap to prevent overflow
            DrawTempChartSmooth();
        }

