        private async void DriversTitle_MouseLeftButtonUp(object sender, System.Windows.Input.MouseButtonEventArgs e)
        {
            var now = DateTime.UtcNow;
            if ((now - _driversTitleLastClickUtc).TotalSeconds > 3) _driversTitleClickCount = 0;
            _driversTitleLastClickUtc = now;
            _driversTitleClickCount++;
            if (_driversTitleClickCount < 5) return;
            _driversTitleClickCount = 0;
            await BulkSearchMissingDrivers();
        }

        private async void BulkDriverSearch_Click(object sender, RoutedEventArgs e) => await BulkSearchMissingDrivers();

        private async Task BulkSearchMissingDrivers()
        {
            try
            {
                var driverSvc = new SMDWin.Services.DriverService();
                var missing = await driverSvc.GetMissingDevicesAsync();
                if (missing.Count == 0)
                {
                    SMDWin.Views.AppDialog.Show(LanguageService.S("Msg", "BulkDriverNone"), LanguageService.S("Msg", "BulkDriverTitle"), SMDWin.Views.AppDialog.Kind.Info);
                    return;
                }

                bool confirm = SMDWin.Views.AppDialog.Confirm(
                    $"Found {missing.Count} missing/errored device(s). This will open {missing.Count} browser tab(s), one search per device. Continue?",
                    "Bulk Driver Search");
                if (!confirm) return;

                // distinct addresses (several devices may have the same hardware ID → the same search)
                var urls = missing.Select(dev => (dev, url: BuildDriverSearchUrl(dev)))
                                  .GroupBy(x => x.url).Select(g => g.First()).ToList();
                // first all the addresses in a single command to the browser (one tab each); otherwise one by one
                if (SMDWin.Services.BrowserLauncher.TryOpenMany(urls.Select(x => x.url).ToList()))
                {
                    AppLogger.Info("BulkSearchMissingDrivers: {Total} searches opened together ({Distinct} distinct)", missing.Count, urls.Count);
                    return;
                }
                int opened = 0, failed = 0, index = 0;
                foreach (var (dev, url) in urls)
                {
                    try
                    {
                        LaunchUrl(url, dev.Name, dev.HardwareId ?? "");
                        opened++;
                    }
                    catch (Exception ex)
                    {
                        failed++;
                        AppLogger.Warning(ex, $"BulkSearchMissingDrivers: skip device '{dev.Name}' (hwId='{dev.HardwareId}')");
                    }
                    // the first request starts the browser (a few seconds); requests sent while it opens used to be lost, which is why only one tab remained
                    await Task.Delay(index++ == 0 ? 3000 : 900);
                }
                AppLogger.Info("BulkSearchMissingDrivers: {Opened} of {Total} searches launched ({Distinct} distinct)", opened, missing.Count, urls.Count);

                if (failed > 0)
                {
                    SMDWin.Views.AppDialog.Show(
                        $"Opened {opened} of {missing.Count} searches — {failed} device(s) could not be launched (see logs for details).",
                        "Bulk Driver Search", SMDWin.Views.AppDialog.Kind.Warning);
                }
            }
            catch (Exception ex) { AppLogger.Debug($"BulkSearchMissingDrivers: {ex.Message}"); }
        }

        private void UpdateStressTimers()
        {
            try
            {
                string stressLabel = _enduranceModeOn ? "ENDURANCE" : "STRESS";
                if (FindName("TxtCpuStressBadgeLabel") is TextBlock lblCpu) lblCpu.Text = stressLabel;
                if (FindName("TxtGpuStressBadgeLabel") is TextBlock lblGpu) lblGpu.Text = stressLabel;

                bool cpuOn = _cpuStress.Running;
                _cpuStressStartUtc = cpuOn ? (_cpuStress.StartedUtc ?? _cpuStressStartUtc ?? DateTime.UtcNow) : null;
                if (FindName("TxtCpuStressTimer") is TextBlock tCpu)
                {
                    string elapsed = cpuOn && _cpuStressStartUtc.HasValue
                        ? FmtStressElapsed(DateTime.UtcNow - _cpuStressStartUtc.Value) : "";
                    int errCount = SMDWin.Services.CpuStressor.IntegrityErrorCount;
                    if (errCount > 0)
                    {
                        tCpu.Text = elapsed + $" · ⚠ {errCount} integrity error(s)";
                        tCpu.ToolTip = "NaN detected in test calculations — a real sign of hardware instability (bit-flip), not just a normal arithmetic overflow. If it persists across multiple sessions at normal temperatures, consider checking RAM (memtest) or an eventual overclock.";
                    }
                    else if (!cpuOn && _cpuStressStartUtc == null && _lastCpuStressHadRun)
                    {
                        tCpu.Text = "✓ Last session: no integrity errors";
                        tCpu.ToolTip = "The test verifies calculation results (FMA), not just temperature — a CPU can be unstable even without overheating.";
                    }
                    else
                    {
                        tCpu.Text = elapsed;
                        tCpu.ToolTip = null;
                    }
                    if (cpuOn) _lastCpuStressHadRun = true;
                }

                bool gpuOn = _gpuStress.IsRunning;
                TrackStressInterval("CPU", cpuOn);
                TrackStressInterval("GPU", gpuOn);
                _gpuStressStartUtc = gpuOn ? (_gpuStress.StartedUtc ?? _gpuStressStartUtc ?? DateTime.UtcNow) : null;
                if (FindName("TxtGpuStressTimer") is TextBlock tGpu)
                {
                    string elapsedGpu = gpuOn && _gpuStressStartUtc.HasValue
                        ? FmtStressElapsed(DateTime.UtcNow - _gpuStressStartUtc.Value) : "";
                    int errCountGpu = SMDWin.Services.GpuStressService.IntegrityErrorCount;
                    if (errCountGpu > 0)
                    {
                        tGpu.Text = elapsedGpu + $" · ⚠ {errCountGpu} integrity error(s)";
                        tGpu.ToolTip = "Divergence detected between the GPU result and the expected value — a real sign of hardware instability (GPU memory, silicon, or driver), not just a normal arithmetic overflow.";
                    }
                    else if (!gpuOn && _gpuStressStartUtc == null && _lastGpuStressHadRun)
                    {
                        tGpu.Text = "✓ Last session: no integrity errors";
                        tGpu.ToolTip = "The test verifies GPU calculation results, not just temperature.";
                    }
                    else
                    {
                        tGpu.Text = elapsedGpu;
                        tGpu.ToolTip = null;
                    }
                    if (gpuOn) _lastGpuStressHadRun = true;
                }

                bool ramDiskOn = _psuStress.IsRunning;
                _ramDiskStressStartUtc = ramDiskOn ? (_psuStress.StartedUtc ?? _ramDiskStressStartUtc ?? DateTime.UtcNow) : null;

                var activeStarts = new[] { _cpuStressStartUtc, _gpuStressStartUtc, _ramDiskStressStartUtc }
                    .Where(x => x.HasValue).Select(x => x!.Value).ToList();
                if (activeStarts.Count > 0)
                {
                    _stressSessionStart    = activeStarts.Min().ToLocalTime();
                    _stressSessionLastSeen = DateTime.Now;
                }
                string ramDiskElapsed = ramDiskOn && _ramDiskStressStartUtc.HasValue
                    ? FmtStressElapsed(DateTime.UtcNow - _ramDiskStressStartUtc.Value) : "";
                if (FindName("TxtRamStressTimer") is TextBlock tRam)
                {
                    int errCountRam = SMDWin.Services.PsuStressService.IntegrityErrorCount;
                    if (errCountRam > 0)
                    {
                        tRam.Text = ramDiskElapsed + $" · ⚠ {errCountRam} integrity error(s)";
                        tRam.ToolTip = "Discrepancy detected between what was written and what was read back from the buffer — a real sign of RAM instability. If it persists across multiple sessions, consider Windows Memory Diagnostic (RAM Memory page) or testing modules individually.";
                    }
                    else if (!ramDiskOn && _ramDiskStressStartUtc == null && _lastRamDiskStressHadRun)
                    {
                        tRam.Text = "✓ Last session: no integrity errors";
                        tRam.ToolTip = "The test verifies what is read back from the buffer against what was written, not just bandwidth.";
                    }
                    else
                    {
                        tRam.Text = ramDiskElapsed;
                        tRam.ToolTip = null;
                    }
                    if (ramDiskOn) _lastRamDiskStressHadRun = true;
                }
                if (FindName("TxtDiskStressTimer") is TextBlock tDisk) tDisk.Text = ramDiskElapsed;

                CheckStressAutoStop();
            }
            catch (Exception ex) { AppLogger.Debug(ex.Message); }
        }

        private static string FmtStressElapsed(TimeSpan ts) =>
            ts.TotalHours >= 1 ? $" · {(int)ts.TotalHours:00}:{ts.Minutes:00}:{ts.Seconds:00}"
                                : $" · {ts.Minutes:00}:{ts.Seconds:00}";

        private async Task RefreshDiskTemperaturesIfDueAsync()
        {
            if (_diskTempPollInFlight) return;
            if ((DateTime.UtcNow - _lastDiskTempPoll).TotalSeconds < 45) return;
            if (!SMDWin.Services.SmartctlService.IsAvailable) return;
            _diskTempPollInFlight = true;
            _lastDiskTempPoll = DateTime.UtcNow;
            try
            {
                if (_allDisks.Count == 0) _allDisks = await _hwService.GetDisksAsync();
                // copy — avoid a race if _allDisks reloads in parallel
                var disks = _allDisks.Where(d => !string.IsNullOrWhiteSpace(d.PhysicalDevicePath)).ToList();

                var readings = await Task.WhenAll(disks.Select(async disk =>
                {
                    try
                    {
                        return (Path: disk.PhysicalDevicePath,
                                Reading: await SMDWin.Services.SmartctlService.ReadTemperatureAsync(disk.PhysicalDevicePath));
                    }
                    catch (Exception ex)
                    {
                        AppLogger.Debug("RefreshDiskTemperatures: {Path}: {Msg}", disk.PhysicalDevicePath, ex.Message);
                        return (Path: disk.PhysicalDevicePath,
                                Reading: new SMDWin.Services.SmartctlTempReading { ErrorMessage = ex.Message });
                    }
                }));
                await Dispatcher.InvokeAsync(() =>
                {
                    foreach (var (path, reading) in readings)
                    {
                        if (reading.Celsius.HasValue)
                        {
                            _diskTempCache[path] = reading.Celsius.Value;
                            double t = reading.Celsius.Value;
                            if (_diskTempMinMax.TryGetValue(path, out var acc))
                                _diskTempMinMax[path] = (Math.Min(acc.min, t), Math.Max(acc.max, t), acc.sum + t, acc.count + 1);
                            else
                                _diskTempMinMax[path] = (t, t, t, 1);
                        }
                        // sleeping disk: keep the last known value (not an error); otherwise there is no reliable value and the row disappears
                        else if (!reading.InStandby) _diskTempCache.Remove(path);
                    }
                    UpdateDiskTempRows();
                });
            }
            catch (Exception ex) { AppLogger.Debug($"RefreshDiskTemperaturesIfDueAsync: {ex.Message}"); }
            finally { _diskTempPollInFlight = false; }
        }

        private void UpdateDiskTempRows()
        {
            if (FindName("DiskTempRowsContainer") is not System.Windows.Controls.StackPanel container) return;
            container.Children.Clear();
            if (_diskTempCache.Count == 0) return;

            foreach (var disk in _allDisks)
            {
                if (!_diskTempCache.TryGetValue(disk.PhysicalDevicePath, out double tempC)) continue;

                var row = new Grid { Margin = new Thickness(12, 1, 12, 1), MinHeight = 32 };
                // The first disk with a sensor gets the chart checkbox (the chart shows the hottest disk)
                if (container.Children.Count == 0)
                {
                    row.Tag = "DiskTemp";
                    row.Cursor = System.Windows.Input.Cursors.Hand;
                    row.Background = System.Windows.Media.Brushes.Transparent;
                    row.MouseLeftButtonUp += SensorRow_Click;
                    row.ToolTip = "Show on chart (hottest drive)";
                    var chk = new Border
                    {
                        Width = 14, Height = 14, CornerRadius = new CornerRadius(3), BorderThickness = new Thickness(1.5),
                        Background = System.Windows.Media.Brushes.Transparent,
                        VerticalAlignment = VerticalAlignment.Center, HorizontalAlignment = System.Windows.HorizontalAlignment.Center,
                    };
                    chk.SetResourceReference(Border.BorderBrushProperty, "CardBorderBrush");
                    try { if (FindName("ChkDiskTemp") != null) UnregisterName("ChkDiskTemp"); } catch (System.Exception __ignored) { SMDWin.Services.AppLogger.Swallowed(__ignored); }
                    RegisterName("ChkDiskTemp", chk);
                    row.Children.Add(chk);
                    if (_slotTags.Contains("DiskTemp"))
                        UpdateCheckbox("DiskTemp", true, TryFindResource("AccentBrush") as Brush ?? System.Windows.Media.Brushes.DodgerBlue);
                }
                row.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(0) });
                row.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star), MinWidth = 120 });
                row.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(70) });
                row.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(62) });
                row.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(62) });
                row.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(0) });

                var labelStack = new StackPanel { Orientation = System.Windows.Controls.Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(4, 0, 0, 0) };
                var textStack = new StackPanel();
                string shortModel = disk.Model.Length > 24 ? disk.Model[..24] + "…" : disk.Model;
                textStack.Children.Add(new TextBlock { Text = LanguageService.S("Disk", "DiskTempLabel", "Disk Temp"), FontSize = Ui.FontM, FontWeight = FontWeights.SemiBold,
                    Foreground = (Brush)TryFindResource("TextPrimaryBrush") ?? System.Windows.Media.Brushes.Black });
                textStack.Children.Add(new TextBlock { Text = shortModel, FontSize = Ui.FontXS,
                    Foreground = (Brush)TryFindResource("TextSecondaryBrush") ?? System.Windows.Media.Brushes.Gray, Opacity = 0.7 });
                labelStack.Children.Add(textStack);
                Grid.SetColumn(labelStack, 1);
                row.Children.Add(labelStack);

                Brush ColorFor(double t) => t >= 55 ? (Brush)TryFindResource("ActionRedBrush") ?? System.Windows.Media.Brushes.Red
                                          : t >= 45 ? (Brush)TryFindResource("OrangeBrush") ?? System.Windows.Media.Brushes.Orange
                                          : (Brush)TryFindResource("AccentBrush") ?? System.Windows.Media.Brushes.DodgerBlue;

                var valueText = new TextBlock
                {
                    Text = $"{TempUnit.Fmt(tempC)}", FontSize = Ui.FontL, FontWeight = FontWeights.SemiBold,
                    Foreground = ColorFor(tempC), TextAlignment = TextAlignment.Right, VerticalAlignment = VerticalAlignment.Center,
                };
                Grid.SetColumn(valueText, 2);
                row.Children.Add(valueText);

                _diskTempMinMax.TryGetValue(disk.PhysicalDevicePath, out var acc);
                bool hasAcc = acc.count > 0;
                TextBlock MinMaxAvgCell(int col, double? val, bool colored)
                {
                    var tb = new TextBlock
                    {
                        Text = val.HasValue ? $"{TempUnit.Fmt(val.Value)}" : "—",
                        FontSize = Ui.FontM, FontWeight = FontWeights.SemiBold,
                        Foreground = (val.HasValue && colored) ? ColorFor(val.Value) : (Brush)TryFindResource("TextSecondaryBrush") ?? System.Windows.Media.Brushes.Gray,
                        TextAlignment = TextAlignment.Right, VerticalAlignment = VerticalAlignment.Center,
                    };
                    Grid.SetColumn(tb, col);
                    return tb;
                }
                row.Children.Add(MinMaxAvgCell(3, hasAcc ? acc.min : (double?)null, colored: false));
                row.Children.Add(MinMaxAvgCell(4, hasAcc ? acc.max : (double?)null, colored: true)); // coloured Max — as with CPU/GPU, it is the most relevant for "how bad it got"
                row.Children.Add(MinMaxAvgCell(5, hasAcc ? acc.sum / acc.count : (double?)null, colored: false));

                container.Children.Add(row);
            }
        }

        private void AutoClearTempBadgeIfStale()
        {
            try
            {
                if (BadgeTemp == null || BadgeTemp.Visibility != Visibility.Visible) return;
                if (_badgeTempLastSeenUtc == DateTime.MinValue) return;
                if ((DateTime.UtcNow - _badgeTempLastSeenUtc).TotalSeconds < BadgeTempGraceSeconds) return;

                UpdateSidebarBadge("Temp", 0, "");
                _badgeTempActive = false;
                _lastTempBadgeLevel = 0;
                _lastTempBadgeCount = 0;
            }
            catch (Exception ex) { AppLogger.Debug(ex.Message); }
        }
    }
}
